  ('d653ab08-d643-5bd3-be43-fd6d9d8ca23e', null, (select id from public.skills where slug = 'read-g12-theme-summary'), null, 'medium',
   $q$How does Mr. Adeyemi's suggestion advance the development of the theme?$q$, $q$[{"text":"It reveals that the laundromat will reopen soon in the same building.","is_correct":false,"misconception_token":"adds-false-detail"},{"text":"It tells Esperanza that her technical photography skills are weak.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It separates the building, which is leaving, from the relationships, which remain, redirecting Esperanza's view of loss.","is_correct":true},{"text":"It shows that he is annoyed that Esperanza is in the way of his customers.","is_correct":false,"misconception_token":"misreads-tone"}]$q$::jsonb, $q$It separates the building, which is leaving, from the relationships, which remain, redirecting Esperanza's view of loss.$q$, $q$"Take pictures of the part that stays" names the distinction the theme rests on. He politely asks to make a suggestion, so he is not annoyed, and he never criticizes her technique.$q$, 'draft', '7aaa60c9-4dd2-53dd-94f3-8c7341e558e5')
