  ('c0ef6529-fa4a-577b-962b-5dd622a2b3fb', null, (select id from public.skills where slug = 'read-g12-word-parts'), null, 'hard',
   $q$"Innovative" shares the root nov with "novice" and "renovation," and the suffix -ive means "tending to." What did Dr. Ainsley mean by calling Lucia's idea "innovative"?$q$, $q$[{"text":"It was the least expensive plan anyone offered","is_correct":false,"misconception_token":"context-only-guess"},{"text":"It came from someone who was new to the museum","is_correct":false,"misconception_token":"overextends-shared-root"},{"text":"It introduced a fresh, original approach","is_correct":true},{"text":"It followed the museum's usual way of doing things","is_correct":false,"misconception_token":"opposite-meaning"}]$q$::jsonb, $q$It introduced a fresh, original approach$q$, $q$Innovative means tending to bring in new ideas or methods, and her plan to pair old scenes with modern photographs was a new approach. Lucia was new to the museum, but the word describes the idea, not the person who offered it.$q$, 'draft', '230ec808-114e-5f94-b5c8-a72e2ad58f48')
